  - { id: st_tomas_3, kind: smalltalk, layer: 1, partner: tomas, text: "The fish plant's on short shifts this month. It's been a long week." }
  - { id: st_tomas_4, kind: smalltalk, layer: 1, partner: tomas, text: "Something you should know about Elena. She forgets to eat if nobody's watching her.", effects: ["mood += 1"] }
  - { id: st_nina_1, kind: smalltalk, layer: 1, partner: nina, text: "The radio says there's a gale warning. It always says that, and I find it restful." }
  - { id: st_nina_2, kind: smalltalk, layer: 1, partner: nina, text: "Mrs Pryce wants a sliced white loaf and my opinion of her son-in-law. She'll only get one of those.", effects: ["mood += 1"] }
